package org.springframework.samples.petclinic.rest.controller.v1;

import java.time.LocalDate;

import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.util.FiscalYears;

/**
 * Membership tenure rules. An owner's tenure is the number of fiscal years elapsed since
 * their registration date (the fiscal year starts on 1 July); level 4 requires a tenure of
 * more than one fiscal year, so a newly created owner (zero tenure) can never exceed level 3.
 */
final class Tenure {

    private Tenure() {
    }

    /** True when more than one fiscal year has elapsed since the owner registered. */
    static boolean exceedsOneYear(Owner owner) {
        LocalDate registered = owner.getRegistrationDate();
        return registered != null && FiscalYears.elapsed(registered, LocalDate.now()) > 1;
    }
}
==== Namesakes
package org.springframework.samples.petclinic.rest.controller.v1;

import java.util.Collection;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Counts owners that are namesakes, i.e. carry the same first name and last name
 * compared case-insensitively.
 */
final class Namesakes {

    private Namesakes() {
    }

    /** Lower-case a value for comparison, treating null as empty. */
    private static String normalize(String value) {
        return value == null ? "" : value.toLowerCase();
    }

    /** Count existing owners sharing the candidate's first and last name. */
    static int count(Collection<Owner> existing, Owner candidate) {
        String firstName = normalize(candidate.getFirstName());
        String lastName = normalize(candidate.getLastName());
        return (int) existing.stream().filter(o ->
            normalize(o.getFirstName()).equals(firstName) && normalize(o.getLastName()).equals(lastName)).count();
    }
}
==== PossibleDuplicates
package org.springframework.samples.petclinic.rest.controller.v1;

import java.util.Collection;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Detects a "soft" duplicate: an owner that is not a hard duplicate but shares an
 * existing owner's last name (compared case-insensitively) and postcode while carrying
 * a different telephone. The different telephone excludes the owner from matching itself.
 */
final class PossibleDuplicates {

    private PossibleDuplicates() {
    }

    /** Lower-case a value for comparison, treating null as empty. */
    private static String normalize(String value) {
        return value == null ? "" : value.toLowerCase();
    }

    /** The id of the earliest existing owner softly matching the candidate, or null when none. */
    static Integer matchId(Collection<Owner> existing, Owner candidate) {
        if (candidate.getPostcode() == null) {
            return null;
        }
        String lastName = normalize(candidate.getLastName());
        return existing.stream()
            .filter(o -> normalize(o.getLastName()).equals(lastName)
                && candidate.getPostcode().equals(o.getPostcode())
                && !candidate.getTelephone().equals(o.getTelephone()))
            .map(Owner::getId)
            .min(Integer::compareTo)
            .orElse(null);
    }
}
